import { test, expect } from '@playwright/test';

test.describe('Optimistic UI Updates for Liking a Post', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/posts');
  });

  test('should optimistically update the like count when a post is liked', async ({ page }) => {
    const post = await page.getByText('Post Title 1');
    const likeButton = await post.getByRole('button', { name: 'Like' });

    await expect(likeButton).toHaveText('Like');
    await likeButton.click();

    await expect(likeButton).toHaveText('Liked');
    await expect(post.getByText('1 Like')).toBeVisible();
  });

  test('should revert the like count if the like action fails', async ({ page }) => {
    const post = await page.getByText('Post Title 2');
    const likeButton = await post.getByRole('button', { name: 'Like' });

    await likeButton.click();

    // Simulate API failure
    await page.route('**/like-post', route => {
      route.fulfill({ status: 500 });
    });

    await likeButton.click();

    await expect(likeButton).toHaveText('Like');
    await expect(post.getByText('0 Likes')).toBeVisible();
  });
});
